// רכיב קרוסלה 

function QuotesCarousel({ quotes, onSelect, intervalMs = 4000 }) {
  const total = quotes.length;
  const [index, setIndex] = useState(0);
  const [anim, setAnim] = useState("");
  const timerRef = useRef(null);
  const dragStart = useRef(null);
  const draggedRef = useRef(false);

  const resetAutoplay = () => {
    if (timerRef.current) clearInterval(timerRef.current);
    if (total <= 1) return;
    timerRef.current = setInterval(() => {
      setIndex((prev) => (prev + 1) % total);
      setAnim("anim-next");
    }, intervalMs);
  };

  useEffect(() => {
    resetAutoplay();
    return () => clearInterval(timerRef.current);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [total, intervalMs]);

  const goNext = () => {
    setIndex((prev) => (prev + 1) % total);
    setAnim("anim-next");
    resetAutoplay();
  };

  const goPrev = () => {
    setIndex((prev) => (prev - 1 + total) % total);
    setAnim("anim-prev");
    resetAutoplay();
  };

  const onPointerDown = (e) => {
    if (e.pointerType === "mouse" && e.button !== 0) return;
    dragStart.current = { x: e.clientX, y: e.clientY };
    draggedRef.current = false;
    if (e.currentTarget.setPointerCapture) {
      try {
        e.currentTarget.setPointerCapture(e.pointerId);
      } catch (err) {}
    }
  };

  const onPointerMove = (e) => {
    const start = dragStart.current;
    if (!start) return;
    const dx = e.clientX - start.x;
    const dy = e.clientY - start.y;
    if (Math.abs(dx) > 8 || Math.abs(dy) > 8) draggedRef.current = true;
    if (Math.abs(dx) > Math.abs(dy) && e.cancelable) e.preventDefault();
  };

  const onPointerUp = (e) => {
    const start = dragStart.current;
    dragStart.current = null;
    if (!start) return;
    const dx = e.clientX - start.x;
    if (Math.abs(dx) >= 40) {
      if (dx < 0) goNext();
      else goPrev();
    } else if (!draggedRef.current) {
      onSelect();
    }
  };

  const onPointerCancel = () => {
    dragStart.current = null;
  };

  return (
    <div
      className="quotes-carousel"
      onPointerDown={onPointerDown}
      onPointerMove={onPointerMove}
      onPointerUp={onPointerUp}
      onPointerCancel={onPointerCancel}
    >
      <QuoteCard top={155} height={139} />
      <p
        key={index}
        className={`quote-carousel-text ${anim}`}
        dir="auto"
        onAnimationEnd={() => setAnim("")}
      >
        {quotes[index]}
      </p>
      {total > 1 && (
        <div className="quote-carousel-dots">
          {quotes.map((_, i) => (
            <span
              key={i}
              className={`quote-carousel-dot ${i === index ? "active" : ""}`}
            />
          ))}
        </div>
      )}
    </div>
  );
}

